import ee
import math

try:
    ee.Initialize(project='earthsense-436113')
except Exception as e:
    ee.Initialize()

# 1. Geometry & Time Definitions
# Approximate Central Valley bounding polygon
geom = ee.Geometry.Polygon(
    [[[-122.8, 34.8],
      [-118.7, 34.8],
      [-118.7, 40.9],
      [-122.8, 40.9],
      [-122.8, 34.8]]],
    None, False
)

periods = {
    'Oct2022': ('2022-10-01', '2022-11-01'),
    'Mar2023': ('2023-03-01', '2023-04-01'),
}

# Candidate GRACE/GRACE-FO datasets (try in order)
candidates = [
    {'id': 'NASA/GRACE/MASS_GRIDS/LAND', 'band': 'lwe_thickness'},
    # Additional plausible IDs (may fail; caught safely)
    {'id': 'JPL/GRACE_GRACE-FO/MASCON_CRI_GRID_RL06', 'band': 'lwe_thickness'},
    {'id': 'JPL/GRACE/MASS_GRIDS/CRI', 'band': 'lwe_thickness'},
]

scale_m = 100000  # coarse scale appropriate for GRACE, >= 1000 as required

def get_period_stats(start, end):
    last_exception = None
    for cand in candidates:
        try:
            col = ee.ImageCollection(cand['id']).select(cand['band']).filterDate(start, end)
            # Global dataset; filterBounds is optional but harmless:
            col = col.filterBounds(geom)
            size = col.size().getInfo()
        except Exception as e:
            last_exception = e
            continue
        if size == 0:
            # Try slight widening (±7 days) to accommodate missing monthly release
            try:
                col2 = ee.ImageCollection(cand['id']).select(cand['band']) \
                    .filterDate(ee.Date(start).advance(-7, 'day'), ee.Date(end).advance(7, 'day')) \
                    .filterBounds(geom)
                size2 = col2.size().getInfo()
            except Exception as e:
                last_exception = e
                continue
            if size2 == 0:
                continue
            else:
                col = col2
                size = size2
        # Compute mean image over available scenes
        img = col.mean()
        # Count valid pixels in region
        try:
            count = img.reduceRegion(
                reducer=ee.Reducer.count(),
                geometry=geom,
                scale=scale_m,
                maxPixels=1e9,
            ).get(cand['band']).getInfo()
        except Exception as e:
            last_exception = e
            continue
        if (count is None) or (int(count) == 0):
            return {'error': 'C2', 'detail': f"No valid pixels after masking for {cand['id']} {start}..{end}"}
        # Mean LWE (cm)
        try:
            mean_val = img.reduceRegion(
                reducer=ee.Reducer.mean(),
                geometry=geom,
                scale=scale_m,
                maxPixels=1e9,
            ).get(cand['band']).getInfo()
        except Exception as e:
            last_exception = e
            continue
        # Validate mean
        if mean_val is None or (isinstance(mean_val, float) and (math.isnan(mean_val) or math.isinf(mean_val))):
            return {'error': 'C3', 'detail': f"Invalid mean (None/NaN/Inf) for {cand['id']} {start}..{end}"}
        # Plausibility check: GRACE LWE in cm typically within ±300 cm
        if isinstance(mean_val, (int, float)) and abs(mean_val) > 500:
            return {'error': 'C3', 'detail': f"Unrealistic LWE {mean_val} cm for {cand['id']}"}
        return {
            'error': None,
            'dataset': cand['id'],
            'band': cand['band'],
            'images': int(size),
            'pixels': int(count),
            'mean_cm': float(mean_val),
        }
    # If all candidates failed to load/compute
    if last_exception is not None:
        # If failures were due to empty collections only, treat as C1; otherwise D.
        # We conservatively return C1 if no images found; but here we couldn't even load.
        return {'error': 'C1', 'detail': 'No images found or datasets unavailable for the given dates.'}
    return {'error': 'C1', 'detail': 'No images found for the given dates.'}

# 2-3. Data Acquisition, Processing, and Validation
results = {}
for key, (start, end) in periods.items():
    results[key] = get_period_stats(start, end)

# Handle error cases
# If any period has an error, emit that code (priority order C1, C2, C3; else D would have been thrown earlier)
for code in ['C1', 'C2', 'C3']:
    if any((results[k].get('error') == code) for k in results):
        # Print minimal diagnostics
        for k in results:
            r = results[k]
            if r.get('error'):
                print(f"{k}: ERROR {r['error']} - {r.get('detail','')}")
            else:
                print(f"{k}: Images={r['images']}, Mean(cm)={r['mean_cm']:.2f}, Pixels={r['pixels']}, Dataset={r['dataset']}")
        print(f"<answer>{code}</answer>")
        raise SystemExit(0)

# 4. Calculation
oct_mean = results['Oct2022']['mean_cm']
mar_mean = results['Mar2023']['mean_cm']

# 5. Output concise stats and final answer
print(f"Oct 2022: Images={results['Oct2022']['images']}, Mean(cm)={oct_mean:.2f}, Pixels={results['Oct2022']['pixels']}, Dataset={results['Oct2022']['dataset']}")
print(f"Mar 2023: Images={results['Mar2023']['images']}, Mean(cm)={mar_mean:.2f}, Pixels={results['Mar2023']['pixels']}, Dataset={results['Mar2023']['dataset']}")
diff = oct_mean - mar_mean
print(f"Diff (Oct - Mar)={diff:.2f} cm")

# 6. Final Answer
if oct_mean is None or mar_mean is None or any([math.isnan(oct_mean), math.isnan(mar_mean)]):
    print("<answer>C3</answer>")
elif oct_mean > mar_mean:
    print("<answer>A</answer>")
else:
    print("<answer>B</answer>")

